{#
/**
 * @file
 * Default theme implementation for the status report.
  *
  * Available variables:
  * - grouped_requirements: Contains grouped requirements.
  *   Each group contains:
  *   - title: The title of the group.
  *   - type: The severity of the group.
  *   - items: The requirement instances.
  *     Each requirement item contains:
  *     - title: The title of the requirement.
  *     - value: (optional) The requirement's status.
  *     - description: (optional) The requirement's description.
  *     - severity_title: The title of the severity.
  *     - severity_status: Indicates the severity status.
  * - requirements: Ungrouped requirements
  *
  * @ingroup themeable
  */
 #}
{% for group in grouped_requirements %}
  <h3 id="{{ group.type }}">{{ group.title }}</h3>
  {% for requirement in group.items %}
    <details>
      <summary role="button">
        {% if requirement.severity_title %}
          <span class="visually-hidden">{{ requirement.severity_title }}</span>
        {% endif %}
        {{ requirement.title }}
      </summary>
      {{ requirement.value }}
      {% if requirement.description %}
        <div>{{ requirement.description }}</div>
      {% endif %}
    </details>
  {% endfor %}
{% endfor %}

{% if target is not empty %}
  {% set attributes = attributes.setAttribute('target', target) %}
{% endif %}
{% if variant is not empty %}
  {% set attributes = attributes.addClass('my-cta-' ~ variant) %}
{% endif %}

<a {{ attributes }} href="{{ href }}">
  {{ text }}
</a>

{#
/**
 * @file
 * Default theme implementation for a three column layout.
 *
 * This template provides a three column 25%-50%-25% display layout, with
 * additional areas for the top and the bottom.
 *
 * Available variables:
 * - in_preview: Whether the plugin is being rendered in preview mode.
 * - content: The content for this layout.
 * - attributes: HTML attributes for the layout <div>.
 *
 * @ingroup themeable
 */
#}
{%
  set classes = [
    'layout',
    'layout--threecol-25-50-25',
  ]
%}
{% if content %}
  <div{{ attributes.addClass(classes) }}>
    {% if content.top %}
      <div {{ region_attributes.top.addClass('layout__region', 'layout__region--top') }}>
        {{ content.top }}
      </div>
    {% endif %}

    {% if content.first %}
      <div {{ region_attributes.first.addClass('layout__region', 'layout__region--first') }}>
        {{ content.first }}
      </div>
    {% endif %}

    {% if content.second %}
      <div {{ region_attributes.second.addClass('layout__region', 'layout__region--second') }}>
        {{ content.second }}
      </div>
    {% endif %}

    {% if content.third %}
      <div {{ region_attributes.third.addClass('layout__region', 'layout__region--third') }}>
        {{ content.third }}
      </div>
    {% endif %}

    {% if content.bottom %}
      <div {{ region_attributes.bottom.addClass('layout__region', 'layout__region--bottom') }}>
        {{ content.bottom }}
      </div>
    {% endif %}
  </div>
{% endif %}

